package io.github.rameshkumark24.bazaarboss.core.ui.style;

import com.badlogic.gdx.graphics.Color;

/**
 * The colour roles of DESIGN.md §2.3. Generated by {@code python -I docs/design/palette.py --java},
 * from the same values as docs/design/palette.json; a guard test compares the two. Never edit by hand,
 * and never mutate a constant: copy it first ({@code new Color(Palette.TEXT)}).
 */
public final class Palette {

    public static final Color SURFACE = rgb(0x101b2b); // surface
    public static final Color SURFACE_RAISED = rgb(0x1e293a); // surface-raised
    public static final Color SURFACE_TONAL = rgb(0x323e50); // surface-tonal
    public static final Color SURFACE_TONAL_PRESSED = rgb(0x414e60); // surface-tonal-pressed
    public static final Color DIVIDER = rgb(0x394353); // divider
    public static final Color TEXT = rgb(0xf5f1ea); // text
    public static final Color TEXT_MUTED = rgb(0xb6becb); // text-muted
    public static final Color TEXT_DISABLED = rgb(0x7f8792); // text-disabled
    public static final Color ACCENT = rgb(0xfcaa2b); // accent
    public static final Color ACCENT_PRESSED = rgb(0xe1901f); // accent-pressed
    public static final Color ON_ACCENT = rgb(0x101b2b); // on-accent
    public static final Color PROFIT = rgb(0x75d78d); // profit
    public static final Color LOSS = rgb(0xf9786a); // loss
    public static final Color SCENE_AWNING = rgb(0xdd6d45); // scene-awning
    public static final Color SCENE_PAPER = rgb(0xf1e7d2); // scene-paper
    public static final Color SCENE_INK = rgb(0x192230); // scene-ink
    public static final Color SCENE_COUNTER = rgb(0x70482b); // scene-counter
    public static final Color SCENE_COUNTER_EDGE = rgb(0x885e41); // scene-counter-edge
    public static final Color SCENE_BRASS = rgb(0xcda448); // scene-brass
    public static final Color SKIN_1 = rgb(0xe1bc9d); // skin-1
    public static final Color SKIN_2 = rgb(0xc99976); // skin-2
    public static final Color SKIN_3 = rgb(0xb77d56); // skin-3
    public static final Color SKIN_4 = rgb(0x996341); // skin-4
    public static final Color SKIN_5 = rgb(0x754932); // skin-5
    public static final Color HAIR = rgb(0x291f18); // hair

    private Palette() {
    }

    private static Color rgb(int rgb) {
        return new Color((rgb << 8) | 0xff);
    }
}
